-- ============================================================================
-- 0029_mundane_equipment_tokens_part2of2.sql
--
-- SRD 5.1 mundane equipment (237 items, CC-BY-4.0) as common 'item' tokens:
-- weapons, armor, adventuring gear, tools, poisons, ammo, trade goods, vehicles.
-- Reuses the violet Items monogram placeholders. Run both parts, any order.
-- Idempotent: skips an item you already have by name. Attribution: SRD 5.1.
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, details)
  select me, v.name, v.image_url, 'item', 'medium',
         jsonb_build_object('kind','item','item', v.item::jsonb)
  from (values
    ('Leatherworker''s Tools', '/icons/items/_mono/L.svg', '{"name":"Leatherworker''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":5}'),
    ('Light hammer', '/icons/items/_mono/L.svg', '{"name":"Light hammer","itemType":"Weapon","rarity":"common","description":"A light hammer.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":2,"damage":"1d4","damageType":"bludgeoning","properties":["Light","Thrown (range 20/60)"]}'),
    ('Linen', '/icons/items/_mono/L.svg', '{"name":"Linen","itemType":"Trade Good","rarity":"common","description":"1 sq. yd. of linen.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":1}'),
    ('Lock', '/icons/items/_mono/L.svg', '{"name":"Lock","itemType":"Adventuring Gear","rarity":"common","description":"A key is provided with the lock. Without the key, a creature proficient with thieves’ tools can pick this lock with a successful DC 15 Dexterity check. Your GM may decide that better locks are available for higher prices.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":1}'),
    ('Longbow', '/icons/items/_mono/L.svg', '{"name":"Longbow","itemType":"Weapon","rarity":"common","description":"A longbow.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":2,"damage":"1d8","damageType":"piercing","properties":["Ammunition (range 150/600)","Two-Handed"]}'),
    ('Longship', '/icons/items/_mono/L.svg', '{"name":"Longship","itemType":"Waterborne Vehicle","rarity":"common","description":"Waterborne vehicle. Speed 3mph.","source":"SRD 5.1, CC-BY-4.0","cost":"10000 gp"}'),
    ('Longsword', '/icons/items/_mono/L.svg', '{"name":"Longsword","itemType":"Weapon","rarity":"common","description":"A longsword","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":3,"damage":"1d8","damageType":"slashing","properties":["Versatile (1d10)"]}'),
    ('Lute', '/icons/items/_mono/L.svg', '{"name":"Lute","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"35 gp","weight":2}'),
    ('Lyre', '/icons/items/_mono/L.svg', '{"name":"Lyre","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":2}'),
    ('Mace', '/icons/items/_mono/M.svg', '{"name":"Mace","itemType":"Weapon","rarity":"common","description":"A mace.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":4,"damage":"1d6","damageType":"bludgeoning"}'),
    ('Magnifying Glass', '/icons/items/_mono/M.svg', '{"name":"Magnifying Glass","itemType":"Adventuring Gear","rarity":"common","description":"This lens allows a closer look at small objects. It is also useful as a substitute for flint and steel when starting fires. Lighting a fire with a magnifying glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite. A magnifying glass grants advantage on any ability check made to appraise or inspect an item that is small or highly detailed.","source":"SRD 5.1, CC-BY-4.0","cost":"100 gp"}'),
    ('Malice', '/icons/items/_mono/M.svg', '{"name":"Malice","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 15 Constitution saving throw or become poisoned for 1 hour. The poisoned creature is blinded.\\n\\n**_Inhaled._** These poisons are powders or gases that take effect when inhaled. Blowing the powder or releasing the gas subjects creatures in a 5-foot cube to its effect. The resulting cloud dissipates immediately afterward. Holding one''s breath is ineffective against inhaled poisons, as they affect nasal membranes, tear ducts, and other parts of the body.","source":"SRD 5.1, CC-BY-4.0","cost":"250 gp"}'),
    ('Manacles', '/icons/items/_mono/M.svg', '{"name":"Manacles","itemType":"Adventuring Gear","rarity":"common","description":"These metal restraints can bind a Small or Medium creature. Escaping the manacles requires a successful DC 20 Dexterity check. Breaking them requires a successful DC 20 Strength check. Each set of manacles comes with one key. Without the key, a creature proficient with thieves’ tools can pick the manacles’ lock with a successful DC 15 Dexterity check. Manacles have 15 hit points.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":6}'),
    ('Mason''s Tools', '/icons/items/_mono/M.svg', '{"name":"Mason''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":8}'),
    ('Maul', '/icons/items/_mono/M.svg', '{"name":"Maul","itemType":"Weapon","rarity":"common","description":"A maul.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":10,"damage":"2d6","damageType":"bludgeoning","properties":["Two-Handed"]}'),
    ('Mess Kit', '/icons/items/_mono/M.svg', '{"name":"Mess Kit","itemType":"Adventuring Gear","rarity":"common","description":"This tin box contains a cup and simple cutlery. The box clamps together, and one side can be used as a cooking pan and the other as a plate or shallow bowl.","source":"SRD 5.1, CC-BY-4.0","cost":"2 sp","weight":1}'),
    ('Midnight tears', '/icons/items/_mono/M.svg', '{"name":"Midnight tears","itemType":"Poison","rarity":"common","description":"A creature that ingests this poison suffers no effect until the stroke of midnight. If the poison has not been neutralized before then, the creature must succeed on a DC 17 Constitution saving throw, taking 31 (9d6) poison damage on a failed save, or half as much damage on a successful one.\\n\\n **_Ingested._** A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing advantage on the saving throw or dealing only half damage on a failed save.","source":"SRD 5.1, CC-BY-4.0","cost":"1500 gp"}'),
    ('Mirror, steel', '/icons/items/_mono/M.svg', '{"name":"Mirror, steel","itemType":"Adventuring Gear","rarity":"common","description":"A mirror.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":0.5}'),
    ('Morningstar', '/icons/items/_mono/M.svg', '{"name":"Morningstar","itemType":"Weapon","rarity":"common","description":"A morningstar","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":4,"damage":"1d8","damageType":"piercing"}'),
    ('Navigator''s tools', '/icons/items/_mono/N.svg', '{"name":"Navigator''s tools","itemType":"Tools","rarity":"common","description":"This set of instruments is used for navigation at sea. Proficiency with navigator''s tools lets you chart a ship''s course and follow navigation charts. In addition, these tools allow you to add your proficiency bonus to any ability check you make to avoid getting lost at sea.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":2}'),
    ('Net', '/icons/items/_mono/N.svg', '{"name":"Net","itemType":"Weapon","rarity":"common","description":"A net.\r\n\r\nA Large or smaller creature hit by a net is restrained until it is freed. A net has no effect on creatures that are formless, or creatures that are Huge or larger. A creature can use its action to make a DC 10 Strength check, freeing itself or another creature within its reach on a success. Dealing 5 slashing damage to the net (AC 10) also frees the creature without harming it, ending the effect and destroying the net.\r\n\r\nWhen you use an action, bonus action, or reaction to attack with a net, you can make only one attack regardless of the number of attacks you can normally make.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":3,"damage":"0","damageType":"bludgeoning","properties":["Special (Net)","Thrown (range 5/15)"]}'),
    ('Oil of taggit', '/icons/items/_mono/O.svg', '{"name":"Oil of taggit","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 13 Constitution saving throw or become poisoned for 24 hours. The poisoned creature is unconscious. The creature wakes up if it takes damage.\\n\\n **_Contact._** Contact poison can be smeared on an object and remains potent until it is touched or washed off. A creature that touches contact poison with exposed skin suffers its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"400 gp"}'),
    ('Orb', '/icons/items/_mono/O.svg', '{"name":"Orb","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as an Arcane Focus.","source":"SRD 5.1, CC-BY-4.0","cost":"20 gp","weight":3}'),
    ('Ox', '/icons/items/_mono/O.svg', '{"name":"Ox","itemType":"Trade Good","rarity":"common","description":"One ox.","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":1500}'),
    ('Padded Armor', '/icons/items/_mono/P.svg', '{"name":"Padded Armor","itemType":"Armor","rarity":"common","description":"Padded armor consists of quilted layers of cloth and batting.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":8,"armorClass":"11 + Dex modifier","dexBonus":"Yes","stealthDisadvantage":true}'),
    ('Painter''s Supplies', '/icons/items/_mono/P.svg', '{"name":"Painter''s Supplies","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":5}'),
    ('Pale tincture', '/icons/items/_mono/P.svg', '{"name":"Pale tincture","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 16 Constitution saving throw or take 3 (1d6) poison damage and become poisoned. The poisoned creature must repeat the saving throw every 24 hours, taking 3 (1d6) poison damage on a failed save. Until this poison ends, the damage the poison deals can''t be healed by any means. After seven successful saving throws, the effect ends and the creature can heal normally. \\n\\n **_Ingested._** A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing advantage on the saving throw or dealing only half damage on a failed save.","source":"SRD 5.1, CC-BY-4.0","cost":"250 gp"}'),
    ('Pan flute', '/icons/items/_mono/P.svg', '{"name":"Pan flute","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"12 gp","weight":2}'),
    ('Paper (one sheet)', '/icons/items/_mono/P.svg', '{"name":"Paper (one sheet)","itemType":"Adventuring Gear","rarity":"common","description":"A sheet of paper","source":"SRD 5.1, CC-BY-4.0","cost":"2 sp"}'),
    ('Parchment (one sheet)', '/icons/items/_mono/P.svg', '{"name":"Parchment (one sheet)","itemType":"Adventuring Gear","rarity":"common","description":"A sheet of parchment","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp"}'),
    ('Pepper', '/icons/items/_mono/P.svg', '{"name":"Pepper","itemType":"Trade Good","rarity":"common","description":"1lb of pepper.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":1}'),
    ('Perfume (vial)', '/icons/items/_mono/P.svg', '{"name":"Perfume (vial)","itemType":"Adventuring Gear","rarity":"common","description":"A vial of perfume.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp"}'),
    ('Pick, miner''s', '/icons/items/_mono/P.svg', '{"name":"Pick, miner''s","itemType":"Adventuring Gear","rarity":"common","description":"A pick for mining.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":10}'),
    ('Pig', '/icons/items/_mono/P.svg', '{"name":"Pig","itemType":"Trade Good","rarity":"common","description":"One pig.","source":"SRD 5.1, CC-BY-4.0","cost":"3 gp","weight":400}'),
    ('Pike', '/icons/items/_mono/P.svg', '{"name":"Pike","itemType":"Weapon","rarity":"common","description":"A pike.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":18,"damage":"1d10","damageType":"piercing","properties":["Reach","Two-Handed"]}'),
    ('Piton', '/icons/items/_mono/P.svg', '{"name":"Piton","itemType":"Adventuring Gear","rarity":"common","description":"A piton for climbing.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":0.25}'),
    ('Plate Armor', '/icons/items/_mono/P.svg', '{"name":"Plate Armor","itemType":"Armor","rarity":"common","description":"Plate consists of shaped, interlocking metal plates to cover the entire body. A suit of plate includes gauntlets, heavy leather boots, a visored helmet, and thick layers of padding underneath the armor. Buckles and straps distribute the weight over the body.","source":"SRD 5.1, CC-BY-4.0","cost":"1500 gp","weight":65,"armorClass":"18","dexBonus":"No","stealthDisadvantage":true,"strRequirement":15}'),
    ('Platinum', '/icons/items/_mono/P.svg', '{"name":"Platinum","itemType":"Trade Good","rarity":"common","description":"1 lb. of platinum.","source":"SRD 5.1, CC-BY-4.0","cost":"500 gp","weight":1}'),
    ('Platinum Piece', '/icons/items/_mono/P.svg', '{"name":"Platinum Piece","itemType":"Trade Good","rarity":"common","description":"In addition, unusual coins made of other precious metals sometimes appear in treasure hoards. The electrum piece (ep) and the platinum piece (pp) originate from fallen empires and lost kingdoms, and they sometimes arouse suspicion and skepticism when used in transactions. An electrum piece is worth five silver pieces, and a platinum piece is worth ten gold pieces.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":0.02}'),
    ('Playing card set', '/icons/items/_mono/P.svg', '{"name":"Playing card set","itemType":"Tools","rarity":"common","description":"This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-­‐‑Dragon Ante). A few common examples appear on the Tools table, but other kinds of gaming sets exist. If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set. Each type of gaming set requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp"}'),
    ('Poison, Basic', '/icons/items/_mono/P.svg', '{"name":"Poison, Basic","itemType":"Poison","rarity":"common","description":"You can use the poison in this vial to coat one slashing or piercing weapon or up to three pieces of ammunition. Applying the poison takes an action. A creature hit by the poisoned weapon or ammunition must make a DC 10 Constitution saving throw or take 1d4 poison damage. Once applied, the poison retains potency for 1 minute before drying.","source":"SRD 5.1, CC-BY-4.0","cost":"100 gp"}'),
    ('Poisoner''s kit', '/icons/items/_mono/P.svg', '{"name":"Poisoner''s kit","itemType":"Tools","rarity":"common","description":"A poisoner’s kit includes the vials, chemicals, and other equipment necessary for the creation of poisons. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to craft or use poisons.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":2}'),
    ('Pole (10-foot)', '/icons/items/_mono/P.svg', '{"name":"Pole (10-foot)","itemType":"Adventuring Gear","rarity":"common","description":"A 10 foot pole.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":7}'),
    ('Pot, iron', '/icons/items/_mono/P.svg', '{"name":"Pot, iron","itemType":"Adventuring Gear","rarity":"common","description":"An iron pot. Capacity: 1 gallon liquid.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":10}'),
    ('Potter''s tools', '/icons/items/_mono/P.svg', '{"name":"Potter''s tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":3}'),
    ('Pouch', '/icons/items/_mono/P.svg', '{"name":"Pouch","itemType":"Adventuring Gear","rarity":"common","description":"A cloth or leather pouch can hold up to 20 sling bullets or 50 blowgun needles, among other things. A compartmentalized pouch for holding spell components is called a component pouch (described earlier in this section).\r\nCapacity: 1/5 cubic foot/6 pounds of gear.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":1}'),
    ('Purple worm poison', '/icons/items/_mono/P.svg', '{"name":"Purple worm poison","itemType":"Poison","rarity":"common","description":"This poison must be harvested from a dead or incapacitated purple worm. A creature subjected to this poison must make a DC 19 Constitution saving throw, taking 42 (12d6) poison damage on a failed save, or half as much damage on a successful one.\r\n\\n\\n\r\n**_Injury._** Injury poison can be applied to weapons, ammunition, trap components, and other objects that deal piercing or slashing damage and remains potent until delivered through a wound or washed off. A creature that takes piercing or slashing damage from an object coated with the poison is exposed to its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"2000 gp"}'),
    ('Quarterstaff', '/icons/items/_mono/Q.svg', '{"name":"Quarterstaff","itemType":"Weapon","rarity":"common","description":"A quarterstaff.","source":"SRD 5.1, CC-BY-4.0","cost":"2 sp","weight":4,"damage":"1d6","damageType":"bludgeoning","properties":["Versatile (1d8)"]}'),
    ('Quiver', '/icons/items/_mono/Q.svg', '{"name":"Quiver","itemType":"Adventuring Gear","rarity":"common","description":"A quiver can hold up to 20 arrows.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":1}'),
    ('Ram, Portable', '/icons/items/_mono/R.svg', '{"name":"Ram, Portable","itemType":"Adventuring Gear","rarity":"common","description":"You can use a portable ram to break down doors. When doing so, you gain a +4 bonus on the Strength check. One other character can help you use the ram, giving you advantage on this check.","source":"SRD 5.1, CC-BY-4.0","cost":"4 gp","weight":35}'),
    ('Rapier', '/icons/items/_mono/R.svg', '{"name":"Rapier","itemType":"Weapon","rarity":"common","description":"A rapier.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":2,"damage":"1d8","damageType":"piercing","properties":["Finesse"]}'),
    ('Rations (1 day)', '/icons/items/_mono/R.svg', '{"name":"Rations (1 day)","itemType":"Adventuring Gear","rarity":"common","description":"Rations consist of dry foods suitable for extended travel, including jerky, dried fruit, hardtack, and nuts.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":2}'),
    ('Reliquary', '/icons/items/_mono/R.svg', '{"name":"Reliquary","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as a holy symbol.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":2}'),
    ('Ring mail', '/icons/items/_mono/R.svg', '{"name":"Ring mail","itemType":"Armor","rarity":"common","description":"This armor is leather armor with heavy rings sewn into it. The rings help reinforce the armor against blows from swords and axes. Ring mail is inferior to chain mail, and it''s usually worn only by those who can''t afford better armor.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":40,"armorClass":"14","dexBonus":"No","stealthDisadvantage":true}'),
    ('Robes', '/icons/items/_mono/R.svg', '{"name":"Robes","itemType":"Adventuring Gear","rarity":"common","description":"Robes, for wearing.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":4}'),
    ('Rod', '/icons/items/_mono/R.svg', '{"name":"Rod","itemType":"Rod","rarity":"common","description":"Can be used as an arcane focus.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp"}'),
    ('Rope, hempen (50 feet)', '/icons/items/_mono/R.svg', '{"name":"Rope, hempen (50 feet)","itemType":"Adventuring Gear","rarity":"common","description":"Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":10}'),
    ('Rope, silk (50 feet)', '/icons/items/_mono/R.svg', '{"name":"Rope, silk (50 feet)","itemType":"Adventuring Gear","rarity":"common","description":"Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":5}'),
    ('Rowboat', '/icons/items/_mono/R.svg', '{"name":"Rowboat","itemType":"Waterborne Vehicle","rarity":"common","description":"Waterborne vehicle. Speed 1.5mph","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":100}'),
    ('Sack', '/icons/items/_mono/S.svg', '{"name":"Sack","itemType":"Adventuring Gear","rarity":"common","description":"A sack. Capacity: 1 cubic foot/30 pounds of gear.","source":"SRD 5.1, CC-BY-4.0","cost":"1 cp","weight":0.5}'),
    ('Saffron', '/icons/items/_mono/S.svg', '{"name":"Saffron","itemType":"Trade Good","rarity":"common","description":"1lb of saffron.","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":1}'),
    ('Sailing Ship', '/icons/items/_mono/S.svg', '{"name":"Sailing Ship","itemType":"Waterborne Vehicle","rarity":"common","description":"Waterborne vehicle. Speed 2mph","source":"SRD 5.1, CC-BY-4.0","cost":"10000 gp"}'),
    ('Salt', '/icons/items/_mono/S.svg', '{"name":"Salt","itemType":"Trade Good","rarity":"common","description":"1lb of salt.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":1}'),
    ('Scale mail', '/icons/items/_mono/S.svg', '{"name":"Scale mail","itemType":"Armor","rarity":"common","description":"This armor consists of a coat and leggings (and perhaps a separate skirt) of leather covered with overlapping pieces of metal, much like the scales of a fish. The suit includes gauntlets.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":45,"armorClass":"14 + Dex modifier (max 2)","dexBonus":"Yes, max 2","stealthDisadvantage":true}'),
    ('Scale, Merchant''s', '/icons/items/_mono/S.svg', '{"name":"Scale, Merchant''s","itemType":"Adventuring Gear","rarity":"common","description":"A scale includes a small balance, pans, and a suitable assortment of weights up to 2 pounds. With it, you can measure the exact weight of small objects, such as raw precious metals or trade goods, to help determine their worth.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":3}'),
    ('Scimitar', '/icons/items/_mono/S.svg', '{"name":"Scimitar","itemType":"Weapon","rarity":"common","description":"A scimitar.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":3,"damage":"1d6","damageType":"slashing","properties":["Finesse","Light"]}'),
    ('Sealing wax', '/icons/items/_mono/S.svg', '{"name":"Sealing wax","itemType":"Adventuring Gear","rarity":"common","description":"For sealing written letters.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp"}'),
    ('Serpent venom', '/icons/items/_mono/S.svg', '{"name":"Serpent venom","itemType":"Poison","rarity":"common","description":"This poison must be harvested from a dead or incapacitated giant poisonous snake. A creature subjected to this poison must succeed on a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one.\r\n\\n\\n\r\n**_Injury._** Injury poison can be applied to weapons, ammunition, trap components, and other objects that deal piercing or slashing damage and remains potent until delivered through a wound or washed off. A creature that takes piercing or slashing damage from an object coated with the poison is exposed to its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"200 gp"}'),
    ('Shawm', '/icons/items/_mono/S.svg', '{"name":"Shawm","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":1}'),
    ('Sheep', '/icons/items/_mono/S.svg', '{"name":"Sheep","itemType":"Trade Good","rarity":"common","description":"One sheep.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":75}'),
    ('Shield', '/icons/items/_mono/S.svg', '{"name":"Shield","itemType":"Shield","rarity":"common","description":"A shield is made from wood or metal and is carried in one hand. Wielding a shield increases your Armor Class by 2. You can benefit from only one shield at a time.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":6}'),
