    ('Silver Piece', '/icons/items/_mono/S.svg', '{"name":"Silver Piece","itemType":"Trade Good","rarity":"common","description":"One gold piece is worth ten silver pieces, the most prevalent coin among commoners. A silver piece buys a laborer''s work for half a day, a flask of lamp oil, or a night''s rest in a poor inn.","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":0.02}'),
