    ('Smith''s tools', '/icons/items/_mono/S.svg', '{"name":"Smith''s tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"20 gp","weight":8}'),
