    ('Spellbook', '/icons/items/_mono/S.svg', '{"name":"Spellbook","itemType":"Adventuring Gear","rarity":"common","description":"Essential for wizards, a spellbook is a leather-­‐‑bound tome with 100 blank vellum pages suitable for recording spells.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":3}'),
