    ('Splint Armor', '/icons/items/_mono/S.svg', '{"name":"Splint Armor","itemType":"Armor","rarity":"common","description":"This armor is made of narrow vertical strips of metal riveted to a backing of leather that is worn over cloth padding. Flexible chain mail protects the joints.","source":"SRD 5.1, CC-BY-4.0","cost":"200 gp","weight":60,"armorClass":"17","dexBonus":"No","stealthDisadvantage":true,"strRequirement":15}'),
