    ('Spyglass', '/icons/items/_mono/S.svg', '{"name":"Spyglass","itemType":"Adventuring Gear","rarity":"common","description":"Objects viewed through a spyglass are magnified to twice their size.","source":"SRD 5.1, CC-BY-4.0","cost":"1000 gp","weight":1}'),
