    ('Studded Leather Armor', '/icons/items/_mono/S.svg', '{"name":"Studded Leather Armor","itemType":"Armor","rarity":"common","description":"Made from tough but flexible leather, studded leather is reinforced with close-set rivets or spikes.","source":"SRD 5.1, CC-BY-4.0","cost":"45 gp","weight":13,"armorClass":"12 + Dex modifier","dexBonus":"Yes"}'),
    ('Tent', '/icons/items/_mono/T.svg', '{"name":"Tent","itemType":"Adventuring Gear","rarity":"common","description":"A simple and portable canvas shelter, a tent sleeps two.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":20}'),
    ('Thieves'' tools', '/icons/items/_mono/T.svg', '{"name":"Thieves'' tools","itemType":"Tools","rarity":"common","description":"This set of tools includes a small file, a set of lock picks, a small mirror mounted on a metal handle, a set of narrow-­‐‑bladed scissors, and a pair of pliers. Proficiency with these tools lets you add your proficiency bonus to any ability checks you make to disarm traps or open locks.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":1}'),
    ('Tinderbox', '/icons/items/_mono/T.svg', '{"name":"Tinderbox","itemType":"Adventuring Gear","rarity":"common","description":"This small container holds flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a torch—or anything else with abundant, exposed fuel—takes an action. Lighting any other fire takes 1 minute.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":1}'),
    ('Tinker''s tools', '/icons/items/_mono/T.svg', '{"name":"Tinker''s tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":10}'),
    ('Torch', '/icons/items/_mono/T.svg', '{"name":"Torch","itemType":"Adventuring Gear","rarity":"common","description":"A torch burns for 1 hour, providing bright light in a 20-­‐‑foot radius and dim light for an additional 20 feet. If you make a melee attack with a burning torch and hit, it deals 1 fire damage.","source":"SRD 5.1, CC-BY-4.0","cost":"1 cp","weight":1}'),
    ('Torpor', '/icons/items/_mono/T.svg', '{"name":"Torpor","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 15 Constitution saving throw or become poisoned for 4d6 hours. The poisoned creature is incapacitated.\r\n\\n\\n\r\n**_Ingested._** A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing advantage on the saving throw or dealing only half damage on a failed save.","source":"SRD 5.1, CC-BY-4.0","cost":"600 gp"}'),
    ('Totem', '/icons/items/_mono/T.svg', '{"name":"Totem","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as a druidic focus.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp"}'),
    ('Trident', '/icons/items/_mono/T.svg', '{"name":"Trident","itemType":"Weapon","rarity":"common","description":"A trident.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":4,"damage":"1d6","damageType":"piercing","properties":["Two-Handed","Thrown (range 20/60)","Versatile (1d8)"]}'),
    ('Truth serum', '/icons/items/_mono/T.svg', '{"name":"Truth serum","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 11 Constitution saving throw or become poisoned for 1 hour. The poisoned creature can''t knowingly speak a lie, as if under the effect of a zone of truth spell.\r\n\\n\\n\r\n**_Ingested._** A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing advantage on the saving throw or dealing only half damage on a failed save.","source":"SRD 5.1, CC-BY-4.0","cost":"150 gp"}'),
    ('Vial', '/icons/items/_mono/V.svg', '{"name":"Vial","itemType":"Adventuring Gear","rarity":"common","description":"For holding liquids. Capacity: 4 ounces liquid.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp"}'),
    ('Viol', '/icons/items/_mono/V.svg', '{"name":"Viol","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":1}'),
    ('Wagon', '/icons/items/_mono/W.svg', '{"name":"Wagon","itemType":"Land Vehicle","rarity":"common","description":"Drawn vehicle.","source":"SRD 5.1, CC-BY-4.0","cost":"35 gp","weight":400}'),
