    ('Whip', '/icons/items/_mono/W.svg', '{"name":"Whip","itemType":"Weapon","rarity":"common","description":"A whip.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":3,"damage":"1d4","damageType":"slashing","properties":["Reach"]}'),
    ('Woodcarver''s tools', '/icons/items/_mono/W.svg', '{"name":"Woodcarver''s tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":5}'),
    ('Wooden staff', '/icons/items/_mono/W.svg', '{"name":"Wooden staff","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as a druidic focus.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":4,"damage":"1d6","damageType":"bludgeoning","properties":["Versatile (1d8)"]}'),
    ('Wyvern poison', '/icons/items/_mono/W.svg', '{"name":"Wyvern poison","itemType":"Poison","rarity":"common","description":"This poison must be harvested from a dead or incapacitated wyvern. A creature subjected to this poison must make a DC 15 Constitution saving throw, taking 24 (7d6) poison damage on a failed save, or half as much damage on a successful one.\r\n\\n\\n\r\n**_Injury._** Injury poison can be applied to weapons, ammunition, trap components, and other objects that deal piercing or slashing damage and remains potent until delivered through a wound or washed off. A creature that takes piercing or slashing damage from an object coated with the poison is exposed to its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"1200 gp"}'),
    ('Yew wand', '/icons/items/_mono/Y.svg', '{"name":"Yew wand","itemType":"Wand","rarity":"common","description":"Can be used as a druidic focus.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":1}')
  ) as v(name, image_url, item)
  where not exists (
    select 1 from public.token_assets t
    where t.owner_id = me and t.token_type = 'item' and t.name = v.name
  );
end $$;
